/** 
 * Processes an input frame. <p>This method must be called on the  {@linkplain #THREAD_NAME background thread}.
 */
@WorkerThread @RequiresNonNull("inputSurfaceTexture") private void processFrame(){
  checkState(Thread.currentThread().getName().equals(THREAD_NAME));
  checkStateNotNull(eglSurface,"No output surface set.");
  inputSurfaceTexture.updateTexImage();
  long presentationTimeNs=inputSurfaceTexture.getTimestamp();
  long presentationTimeUs=presentationTimeNs / 1000;
  inputSurfaceTexture.getTransformMatrix(textureTransformMatrix);
  ((ExternalCopyFrameProcessor)frameProcessors.get(0)).setTextureTransformMatrix(textureTransformMatrix);
  for (int i=0; i < frameProcessors.size() - 1; i++) {
    Size intermediateSize=frameProcessors.get(i).getOutputSize();
    GlUtil.focusFramebuffer(eglDisplay,eglContext,eglSurface,framebuffers[i],intermediateSize.getWidth(),intermediateSize.getHeight());
    clearOutputFrame();
    frameProcessors.get(i).drawFrame(presentationTimeUs);
  }
  GlUtil.focusEglSurface(eglDisplay,eglContext,eglSurface,outputWidth,outputHeight);
  clearOutputFrame();
  getLast(frameProcessors).drawFrame(presentationTimeUs);
  EGLExt.eglPresentationTimeANDROID(eglDisplay,eglSurface,presentationTimeNs);
  EGL14.eglSwapBuffers(eglDisplay,eglSurface);
  if (debugPreviewEglSurface != null) {
    GlUtil.focusEglSurface(eglDisplay,eglContext,debugPreviewEglSurface,debugPreviewWidth,debugPreviewHeight);
    clearOutputFrame();
    getLast(frameProcessors).drawFrame(presentationTimeUs);
    EGL14.eglSwapBuffers(eglDisplay,debugPreviewEglSurface);
  }
  checkState(pendingFrameCount.getAndDecrement() > 0);
}
